-- RD1 Spirits (family 'RD One'): rd1spirits.com importer, applied 2026-10-12
update cellar.makers set website = coalesce(website, 'https://rd1spirits.com'), country = coalesce(country, 'US'), updated_at = now() where id = '4d105f03-b3d8-4852-870e-62c22672de6f';
update cellar.products set age_years = 4.0, age_label = '4 yr', nas = false, finish = 'French Oak', specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://rd1spirits.com/cdn/shop/files/RD1_Spirits_French_Oak_With_Staves_1000x1000.jpg'), producer = coalesce(producer, 'RD1 Spirits'), producer_id = coalesce(producer_id, '4d105f03-b3d8-4852-870e-62c22672de6f'::uuid), source = 'maker', source_url = 'https://rd1spirits.com/pages/finished-with-french-oak', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = 'e34b9f29-8a3a-426c-9284-82db8a16e536' and facts_verified_at is null;
update cellar.products set age_years = 4.0, age_label = '4 yr', nas = false, finish = 'Brazilian Amburana Wood', specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://rd1spirits.com/cdn/shop/files/RD1_Spirits_Amburana_with_Wood_1000x1000.jpg'), producer = coalesce(producer, 'RD1 Spirits'), producer_id = coalesce(producer_id, '4d105f03-b3d8-4852-870e-62c22672de6f'::uuid), source = 'maker', source_url = 'https://rd1spirits.com/pages/finished-with-brazilian-amburana-wood', source_checked_at = now(), discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity) where id = '48eec957-f43b-4127-9edc-3ebf295a4eaa' and facts_verified_at is null;
update cellar.products set spirit_type = 'blend', finish = 'Japanese Mizunara and French Oak', specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://rd1spirits.com/cdn/shop/files/MuseKY126-sm_1000x1000.jpg'), producer = coalesce(producer, 'RD1 Spirits'), producer_id = coalesce(producer_id, '4d105f03-b3d8-4852-870e-62c22672de6f'::uuid), source = 'maker', source_url = 'https://rd1spirits.com/pages/mizurana-and-french-oak-finish', source_checked_at = now(), discontinued = false, catalog_included = catalog_included or is_core_range, rarity = coalesce(rarity, 'allocated'::cellar.rarity) where id = 'fa424417-d90e-4763-9ad2-9d1f06202e73' and facts_verified_at is null;
update cellar.products set source_checked_at = now() where id in ('4b49e3d0-8f2f-4bfd-949a-32ca9878e34c', 'e34b9f29-8a3a-426c-9284-82db8a16e536', '48eec957-f43b-4127-9edc-3ebf295a4eaa', 'fa424417-d90e-4763-9ad2-9d1f06202e73');
update cellar.products set source = 'maker', source_url = 'https://rd1spirits.com/pages/kentucky-straight-bourbon', discontinued = false, is_core_range = true, catalog_included = true, rarity = coalesce(rarity, 'shelf'::cellar.rarity), producer = coalesce(producer, 'RD1 Spirits'), producer_id = coalesce(producer_id, '4d105f03-b3d8-4852-870e-62c22672de6f'::uuid), specs = coalesce(specs, '{}'::jsonb) || jsonb_build_object('source_image_url', 'https://rd1spirits.com/cdn/shop/files/RD1_Spirits_SBW_With_Pour-min_a15f64e8-6e38-45d7-85bd-db5f5ac6d598_1000x1000.jpg') where id = '4b49e3d0-8f2f-4bfd-949a-32ca9878e34c' and facts_verified_at is null;
insert into cellar.products (type, status, source, specs, name, brand, brand_family, expression, producer, producer_id, proof, age_years, age_label, nas, expression_type, mash_style, mash_bill, spirit_type, bottled_in_bond, barrel_proof, finish, msrp_usd, is_core_range, catalog_included, aliases, image_url, source_url, source_checked_at, rarity)
select 'bourbon', 'confirmed', 'maker', case when r.img is null then '{}'::jsonb else jsonb_build_object('source_image_url', r.img) end, r.n, r.f, r.f, r.x, r.pr, r.mk::uuid, r.p, r.ay, r.al, r.nas, r.et::cellar.expression_type, r.ms::cellar.mash_style, r.mb, r.st::cellar.spirit_type, r.bib, r.bp, r.fin, r.msrp, r.core, true, coalesce(r.al2, '{}'::text[]), null, r.u, now(), r.rar::cellar.rarity
from jsonb_to_recordset($j$[{"n":"RD One Double Finished in Oak and Maple Barrels","rar":"shelf","f":"RD One","x":"Double Finished in Oak and Maple Barrels","p":99.9,"ay":4.0,"al":"4 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":false,"fin":"French Oak and Maple","msrp":null,"core":true,"al2":[],"img":"https://rd1spirits.com/cdn/shop/files/RD1_Spirits_Double_Finish_with_Wood_1000x1000.jpg","u":"https://rd1spirits.com/pages/double-finished-in-oak-and-maple-barrels","pr":"RD1 Spirits","mk":"4d105f03-b3d8-4852-870e-62c22672de6f"},{"n":"RD One 10 Year Amburana Finish","rar":"allocated","f":"RD One","x":"10 Year Amburana Finish","p":117.78,"ay":10.0,"al":"10 yr","nas":false,"et":"standard","ms":"unknown","mb":null,"st":"bourbon","bib":false,"bp":true,"fin":"Brazilian Amburana Wood","msrp":null,"core":false,"al2":[],"img":"https://rd1spirits.com/cdn/shop/files/RD1_10_Year_Amburana_Bourbon_Pour_1000x1000.jpg","u":"https://rd1spirits.com/pages/ten-year-amburana-finish","pr":"RD1 Spirits","mk":"4d105f03-b3d8-4852-870e-62c22672de6f"}]$j$::jsonb) as r(n text, f text, x text, p numeric, ay numeric, al text, nas bool, et text, ms text, mb text, st text, bib bool, bp bool, fin text, msrp numeric, core bool, al2 text[], img text, u text, pr text, mk text, rar text)
where not exists (select 1 from cellar.products e where e.type = 'bourbon' and e.merged_into is null and coalesce(e.brand_family, '') = coalesce(r.f, '') and coalesce(e.expression, '') = coalesce(r.x, '') and coalesce(e.release_label, '') = '');